TLM.f("Sancti/08-25",{"officium":"S. Ludovici Confessoris","rule":["Evangelium non appropriatum","vide C5;","Gloria"],"fallback":"Commune/C5","from":{"Graduale":"Commune/C5","GradualeP":"Commune/C5","Tractus":"Commune/C5"},"sections":{"Introitus":[{"k":"ref","la":"Ps 36:30-31"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 36:1"},{"k":"text","la":"Noli æmulári in malignántibus: neque zeláveris faciéntes iniquitátem."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Deus, qui beátum Ludovícum Confessórem tuum de terréno regno ad cœléstis regni glóriam transtulísti: ejus, quǽsumus, méritis et intercessióne; Regis regum Jesu Christi, Fílii tui, fácias nos esse consórtes:"},{"k":"macro","name":"Qui tecum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 10:10-14"},{"k":"text","la":"Justum dedúxit Dóminus per vias rectas, et ostendit illi regnum Dei, et dedit illi sciéntiam sanctórum: honestávit illum in labóribus, et complévit labores illíus. In fraude circumveniéntium illum áffuit illi, et honéstum fecit illum. Custodívit illum ab inimícis, et a seductóribus tutávit illum, et certámen forte dedit illi, ut vínceret et sciret, quóniam ómnium poténtior est sapiéntia. Hæc vénditum justum non derelíquit, sed a peccatóribus liberávit eum: descendítque cum illo in fóveam, et in vínculis non derelíquit illum, donec afférret illi sceptrum regni, et poténtiam advérsus eos, qui eum deprimébant: et mendáces osténdit, qui maculavérunt illum, et dedit illi claritátem ætérnam, Dóminus, Deus noster."}],"Graduale":[{"k":"ref","la":"Ps 91:13; 91:14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini."},{"k":"ref","la":"Ps 91:3"},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem. Allelúja, allelúja"},{"k":"ref","la":"Ja 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Jas 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja."},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus et ornávit eum: stolam glóriæ índuit eum. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 91:13; 91:14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini."},{"k":"ref","la":"Ps 91:3"},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem."},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 19:12-26"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis parábolam hanc: Homo quidam nóbilis ábiit in regionem longínquam accípere sibi regnum, et revérti. Vocátis autem decem servis suis, dedit eis decem mnas, et ait ad illos: Negotiámini, dum vénio. Cives autem ejus óderant eum: et misérunt legatiónem post illum, dicéntes: Nólumus hunc regnáre super nos. Et factum est, ut redíret accépto regno: et jussit vocári servos, quibus dedit pecúniam, ut sciret, quantum quisque negotiátus esset. Venit autem primus, dicens: Dómine, mna tua decem mnas acquisívit. Et ait illi: Euge, bone serve, quia in módico fuísti fidélis, eris potestátem habens super decem civitátes. Et alter venit, dicens: Dómine, mna tua fecit quinque mnas. Et huic ait: Et tu esto super quinque civitátes. Et alter venit, dicens: Dómine, ecce mna tua, quam hábui repósitam in sudário: tímui enim te, quia homo austérus es: tollis, quod non posuísti, et metis, quod non seminásti. Dicit ei: De ore tuo te júdico, serve nequam. Sciébas, quod ego homo austérus sum, tollens, quod non pósui, et metens, quod non seminávi: et quare non dedísti pecúniam meam ad mensam, ut ego véniens cum usúris útique exegíssem illam? Et astántibus dixit: Auferte ab illo mnam et date illi, qui decem mnas habet. Et dixérunt ei: Dómine, habet decem mnas. Dico autem vobis: Quia omni habénti dábitur, et abundábit: ab eo autem, qui non habet, et, quod habet, auferétur ab eo."}],"Offertorium":[{"k":"ref","la":"Ps 88:25"},{"k":"text","la":"Véritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut, sicut beátus Ludovícus Conféssor tuus, spretis mundi oblectaméntis, soli Regi Christo placére stúduit; ita ejus orátio nos tibi reddat accéptos."},{"k":"macro","name":"Per eundem"}],"Communio":[{"k":"ref","la":"Matt 24:46-47"},{"k":"text","la":"Beátus servus, quem, cum vénerit dóminus, invénerit vigilántem: amen, dico vobis, super ómnia bona sua constítuet eum. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Deus, qui beátum Confessórem tuum Ludovícum mirificásti in terris, et gloriósum in cœlis fecísti: eúndem, quǽsumus, Ecclésiæ tuæ constítue defensórem."},{"k":"macro","name":"Per Dominum"}]},"hr":{"52236fd7918c9b03":{"t":"Ps 36, 30-31, Ps 36, 1\n(Ps 36, 30-31) Pravednikova usta govore mudrost i jezik njegov kazuje pravdu. Zakon je Božji u srcu njegovu. (Ps 36, 1) Ne zaviđaj sreći grešnika i ne žesti se radi zlotvora.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 36, 30-31) Pravednikova usta govore mudrost i jezik njegov kazuje pravdu. Zakon je Božji u srcu njegovu.","kn":"(Ps. 36, 30, 31). Pravednikova usta govore mudrost i njegov jezik kazuje pravdu. Zakon je Božji u njegovu srcu i njegove noge ne će posrnuti. (Aleluja, Aleluja.) (Ps. 36, 1). Ne zaviđaj sreći ^rješnika i zlotvora! Slava Ocu. Pravednikova.","knRef":"Kniewald 1942, str. 814–815 (snimka 408) (OCR)"},"bde9cbb7affe62e1":{"t":"<i>Pomolimo se</i>.\nBože, koji si blaženog Ljudevita priznavaoca svoga prenio iz zemaljskog kraljevstva u slavu vječnoga, učini nas, molimo, po njegovim zaslugama i zagovoru službenicima Kralja kraljeva Isusa Krista Sina svoga:\n<i>koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si blaženog Ljudevita, priznavaoca svoga', iz zemaljskoig kraljevstva prenio u slaivu nebeskog carstva, molimo Te, đa nsis njegovim zagovorom i zaslugama učiniš dionicima slave Kralja kraljeva, Isusa Krista, Sina Tvo'ga, koji s TO’bO'm živi i kralj uje ...","knRef":"Kniewald 1942, str. 690–691 (snimka 346) (OCR)"},"e83d5e42a8b3608d":{"t":"Mudr 10, 10-14\nČitanje knjige Mudrosti. Gospodin je pravim putem vodio pravednika, pokazao mu Božje kraljevstvo, udijelio mu znanje svetih, obogatio ga u naporima i oplodio mu rad. Očuvao ga od varalica i obogatio ga. Zaštitio ga od neprijatelja, čuvao od zasjeda, dao mu da pobjedi u teškoj borbi i spoznao je da je mudrost jača od svega. Ona nije napustila pravednika, kada je bio prodan, nego ga je oslobodila iz ruku grješnika. I sašla je s njim u jamu i nije ga ostavila u lancima, dok mu nije pribavila vladarsko žezlo i vlast nad tlačiteljima. One koji su ga crnili otkrila je kao lašce, a njemu je Bog naš Gospodin udijelio vječnu slavu.","kn":"Čitanje Knjige mudrosti (10, 10-14). Goispodin je pravednika vodio pravim putem i pokazao mu kraljevstvo Božje i udijelio mu znanje svetih i obogatio ga u naporima i oplodio -mu rad. I pomogao mu je protiv onih, koji su ga htjeli prevariti i obogatio ga je. Štitio ga je od neprijatelja i očuvao dd 1 zasjeda i dao mu da pobijedi u teškoj borbi i da i upozna, kako je mudrost jača od svega. Ova nije [ zapustila pravednika, kad je bio prodan, nego ga I je oslobodila iz ruku grješndka. I sašla je s njim u I jamu i nije ga zapustila u lancima, sve dok mu nije pribavila kraljevskoga žezla i vlasti nad tlačiteljima. One, koji su ga ocrnili, pokaza,la je lašctma, a njemu je udijelio vječnu slavu Gospodin Bog naš.","knRef":"Kniewald 1942, str. 792–793 (snimka 397) (OCR)"},"929d73ef8c983301":{"t":"Ps 91, 13-14, Ps 91, 3\n(Ps 91, 13-14) Kao palma cvjeta i kao libanski cedar raste pravednik u domu Gospodnjem. (Ps 91, 3) Jutrom naviješta milosrđe tvoje i noću tvoju vjernost.\n\nJak 1, 12\n<i>Aleluja</i>, <i>aleluja</i>.\nBlago čovjeku koji nadvlada napast, jer kad bude prokušan, primit će krunu života. <i>Aleluja</i>.","kn":"(Ps. 91, 13, 14). Pravednik i’aste poput paome i libanonskog cedra u domu Gospodnjem. Ra.no jutrom naviješta Tvoje milosrđe i noću Tvoju vjernost.\n\nAleluja, aleiuja. (Jak. 1, 12) Blago čovjeku, koji pretrpi napast, jer će primiti vijenac slave, kad bude prokušan, aleluja.","knRef":"Kniewald 1942, str. 786–787 (snimka 394) (OCR)"},"8e24ac5ac11b95c8":{"t":"Lk 19, 12-26\nSlijedi sveto Evanđelje po Luki. U ono vrijeme reče Isus svojim učenicima ovu usporedbu: Neki čovjek ugledna roda pođe u daleku zemlju da primi kraljevstvo i da se povrati poslije toga. Pozove svojih deset slugu, dade im deset mina i reče im: Trgujte dok se ja ne vratim. Njegovi su ga građani mrzili, pa su za njim poslali vjesnike da mu kažu: Nećemo da ovaj vlada nad nama! Kada je preuzeo kraljevstvo, vrati se, dozove sluge kojima je predao novac, da zna koliko je koji stekao. Dođe prvi i reče: Gospodaru, tvoja mina donijela je deset mina. On mu odgovori: Dobro, slugo, dobri, jer si u malom bio vjeran, ti ćeš vladati nad deset gradova. A dođe i drugi i reče: Gospodaru, tvoja je mina donijela pet mina. I ovom reče: I ti budi nad pet gradova. A dođe i treći, koji reče: Gospodaru, evo tvoje mine, koju sam čuvao u rupcu. Ja sam se tebe bojao, jer si oštar čovjek i uzimaš što nisi ostavio i žanješ što nisi sijao. Odgovori mu: Zli slugo, sudim te po tvojim riječima. Znao si da sam oštar čovjek, da uzimam što nisam ostavio i žanjem što nisam sijao. Zašto nisi moj novac dao u promet, da kada dođem, primim ga s kamatama. I naredi prisutnima: Oduzmite mu minu i dajte onome koji ih ima deset. Oni mu kažu: Gospodaru, on ima deset mina. A ja vam kažem da će se dati onome koji već ima, i on će uživati obilno, a od onoga, koji nema, oduzet će se i ono, što ima.","kn":"t Slijedi sv. evanđelje po Luki (19, 12-26). U ono vrije'me reče Isus svojim učenicima lOvu prispcudobu : Neki plemenit čo-vjek pođe u daleku zemlju, da primi kraljevsko dostojanstvo i da se vrati. I pozove svojih deset slugu, dalde im deset mina i reče: Trgujte, do'k se vratim. A njegovi su ga građani mrzili, te su za njim poslali vjesnike, da mu kažu: Ne ćemo, da ovaj vlada nad nama! Kad je primio kraljevsko dostojanstvo, vrati se i dozove sluge, kojima je bio predao novac, da zna, koliko je 'koji stekao. Dođe prvi i reče: Gospodaru, tvoja je mina donijela deset mina. On mu -odgo'vori: Doibro, slugo dobri! Jer iS'i bio vjeran u maloj stvari, ti ćeš vladati nad deset gradova. A dođe i drugi i reče: Gospodaru, tvoja je mina donijela pet mina. I ovom reče: I ti budi nad pet gradova. A dođe i drugi i reče: Gospodaru, evo tvoje mine, koju sam čuvao u rupcu, jer sam se tebe bojaO', ka'd si oštar čovjek i uzimaš , što nijesi ostavio i žanješ, što nijesl sijao. Odgovori mu: Zli slugo, sudim te po tvojim riječima. Znao si, da sam oštar čovje'k, da uzimam, što nijesam ostavio i žanjem, što nijesam sijao. Zašto nijesi dao moga novca u promet, da kada dođem, primim 'ga s kama tima? I naredi prisutnima: Uzmite minu od njega i dajte je onomu, koji ih ima deset. Oni ;mu'kažu: Gospodaru, on ima 'deset mina. A ja vam kažem, da će se dati onomu, koji već ima i uživat će obilno, a od onoga, koji nema' uzet će se i ono što ima.","knRef":"Kniewald 1942, str. 690–691 (snimka 346) (OCR)"},"88bea9a296c140ac":{"t":"Ps 88, 25\nMoja će vjernost i moje milosrđe biti s njime, i svojim ću imenom uzdići njegovu moć.","kn":"(Ps. 88, 25). Istina je moja i milosrđe moje B njime i u ime će se moje uzdići moć njegova.","knRef":"Kniewald 1942, str. 452–453 (snimka 227) (OCR)"},"873d2849a0bff4b6":{"t":"Podaj molimo, svemogući Bože, da nas molitva blaženoga Ljudevita priznavaoca tvoga tako učini tebi milima kao što je on nastojao prezrevši naslade svijeta ugoditi jedinomu Kralju Kristu.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, svemogući Bože, kao što je blaiženi Ljudevit, priznavalac Tvoj, prezrevši slasti ovoga svijeta: nastoja'O ugoditi samo Kristu-Kralju, tako da nas njegova molitva učini prijatnima Tebi, po istom G. n.","knRef":"Kniewald 1942, str. 690–691 (snimka 346) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"56842ed674d6e163":{"t":"Mt 24, 46-47\nBlago slugi koga gospodar nađe budna, kad dođe. Zaista vam kažem: Postavit će ga nad svim imanjem svojim.","kn":"(Mt. 24, 46-47). Blago onomu slugi, koga nađe njegov gospodar budna, kad dođe! zaista vam kažem, da će ga postaviti nad svim imanjem svojim.","knRef":"Kniewald 1942, str. 816–817 (snimka 409) (OCR)"},"d51b1c0e2f769f71":{"t":"<i>Pomolimo se</i>.\nBože, koji si blaženog priznavaoca svoga Ljudevita proslavio na zemlji i učinio slavnim na na nebu: postavi ga, molimo, za branitelja svoje Crkve.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si blaženog Ljudevita, priznavao'ca, O'bdari'O na zemlji i slavnim učinio na nebu, učini ga. molimo, i braniteljem Crkve svoje, po G. n.","knRef":"Kniewald 1942, str. 690–691 (snimka 346) (OCR)"}},"variants":{"paschal":{"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Jas 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja"},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus et ornávit eum: stolam glóriæ índuit eum. Allelúja."}]}}});
